create table xxcus.xxfnd_lookup_values_tl (
    lookup_type           varchar2(30 byte) not null enable,
    lookup_code           varchar2(30 byte) not null enable,
    language_code         varchar2(10 byte) not null enable,
    meaning               varchar2(200 byte) not null enable,
    description           varchar2(500 byte),
    created_by            varchar2(255 byte) not null enable,
    creation_date         timestamp(6) not null enable,
    last_updated_by       varchar2(255 byte) not null enable,
    last_update_date      timestamp(6) not null enable,
    last_update_login     varchar2(255 byte),
    object_version_number number default 1 not null enable
);

alter table xxcus.xxfnd_lookup_values_tl
    add constraint xxfnd_lookup_values_tl_pk
        primary key ( lookup_type,
                      lookup_code,
                      language_code )
            using index enable;


